function deepFind(obj, searchKey) {
    // Check if the object is an object (i.e., it's not null)
    if (obj == null || typeof obj !== 'object') {
        throw new Error("The provided argument must be an object.");
    }

    let result = [];

    const traverse = (node, prefix = '') => {
        for (let key in node) {
            if (typeof node[key] === 'object' && node[key] !== null) {
                const subResult = traverse(node[key], `${prefix}${key}.`);
                result.push(...subResult);
            } else if (key === searchKey) {
                result.push(`${prefix}${searchKey}`);
            }
        }
    };

    traverse(obj);

    return result;
}

